def gen(rng):
    ops = '+-*/^'
    leaves = 'abcxyzABCXYZ0123456789'
    def rand_expr(n_ops, p):
        out = []
        need = 1
        left = n_ops
        while need > 0:
            if left > 0 and (need == 1 or rng.random() < p):
                out.append(rng.choice(ops))
                left -= 1
                need += 1
            else:
                out.append(rng.choice(leaves))
                need -= 1
        return ''.join(out)
    def depth_of(e):
        st = []
        d = 0
        for c in e:
            if c in ops:
                st.append(2)
                d = max(d, len(st))
            else:
                while st:
                    st[-1] -= 1
                    if st[-1] == 0:
                        st.pop()
                    else:
                        break
        return d
    def safe_expr(n_ops, p):
        while True:
            e = rand_expr(n_ops, p)
            if depth_of(e) <= 4500:
                return e
            p = 0.5
    tests = ['x', '7', '+ab', '*+ab-cd', '-/a^bc*de', '^^abc', '+a+b+cd', '++++abcde', '-A-B-C-D-E-F0']
    for k in range(1, 9):
        for _ in range(3):
            tests.append(rand_expr(k, rng.choice([0.4, 0.5, 0.7])))
    for _ in range(8):
        tests.append(rand_expr(rng.randint(9, 60), rng.choice([0.5, 0.6, 0.8])))
    tests.append('+' * 4990 + ''.join(rng.choice(leaves) for _ in range(4991)))
    tests.append(''.join(rng.choice(ops) + rng.choice(leaves) for _ in range(4990)) + rng.choice(leaves))
    tests.append(safe_expr(49999, 0.5))
    tests.append(safe_expr(49999, 0.52))
    tests.append(safe_expr(49999, 0.45))
    return tests
